//! The server's wire types, generated by `build.rs` from
//! `server/generated/wire.schema.json`: the client's types are the server's.

#[allow(clippy::all, clippy::pedantic, dead_code, unused_qualifications)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/wire.rs"));
}

pub use generated::*;

use serde::Deserialize;

/// A message from a session stream: a chunk this client knows, or one from a
/// newer server, which it skips.
#[derive(Debug, Clone, Deserialize)]
#[serde(untagged)]
pub enum IncomingChunk {
    Known(StreamChunk),
    Unknown(serde_json::Value),
}
